import json,numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
s=json.load(open('/app/output/spec.json'))
joints=s['proprio']['joints']; jp=np.array(s['proprio']['position_m']); axes=np.array(s['proprio']['axis'])
names=s['links']['names']; parents=dict(zip(names,s['links']['parent'])); linkj=dict(zip(names[1:],joints))
cam=s['cameras']['room_camera']['pose']; C=np.array(cam['position_m']); F=np.array(cam['forward']); U=np.array(cam['up']); R=np.array(cam['right']); f=128/np.tan(np.pi/8)
def unproject(uv,z):
    ray=F+(uv[0]-127.5)/f*R-(uv[1]-127.5)/f*U
    return C+ray*(z-C[2])/ray[2]
def project(p):
    d=np.asarray(p)-C
    return np.array([127.5+f*(d@R)/(d@F),127.5-f*(d@U)/(d@F)])
def transform(q,link):
    chain=[]
    while link and link!='pelvis':
        chain.insert(0,linkj[link]);link=parents[link]
    T=np.eye(4)
    for j in chain:
        i=joints.index(j); rot=Rotation.from_rotvec(axes[i]*q.get(j,0)).as_matrix(); J=np.eye(4);J[:3,:3]=rot;J[:3,3]=jp[i]-rot@jp[i];T=T@J
    return T

def point(q,link,p):
    T=transform(q,link);return T[:3,:3]@p+T[:3,3]
if __name__=='__main__':
    for name,uv in [('dark',(82,102)),('white',(139,157)),('barwhite',(127,102)),('bardark',(167,131))]:
        print(name,unproject(uv,.83))
